    [HttpGet("{id}/sitzplan")]
    public async Task<ActionResult<SitzplanDto>> GetSitzplan(string id)
    {
        var sitzplan = await veranstaltungenService.GetSitzplanAsync(id);
        if (sitzplan is null)
        {
            return NotFound();
        }

        return Ok(sitzplan);
    }
}

