316	                foreach (var position in request.Positionen)
317	                {
318	                    var kategorie = veranstaltung.Preiskategorien.First(p => p.Id == position.PreiskategorieId);
319	                    gesamtpreis += kategorie.Preis;
320	                    positionen.Add(new Buchungsposition
321	                    {
322	                        BuchungId = buchung.Id,
323	                        SitzplatzCode = position.SitzplatzCode,
324	                        PreiskategorieId = kategorie.Id,
325	                        PreisSnapshot = kategorie.Preis,
326	                    });
327	                }
328	
329	                buchung.Gesamtpreis = gesamtpreis;
330	
331	                var belegungen = request.Positionen.Select(position => new Sitzplatzbelegung
332	                {
333	                    VeranstaltungId = veranstaltungId,
334	                    SitzplatzCode = position.SitzplatzCode,
335	                    BuchungId = buchung.Id,
336	                }).ToList();
337	
338	                await using var transaction = await db.Database.BeginTransactionAsync();
339	                db.Buchungen.Add(buchung);
340	                db.Buchungspositionen.AddRange(positionen);
341	                db.Sitzplatzbelegungen.AddRange(belegungen);
342	
343	                try
344	                {
345	                    await db.SaveChangesAsync();
346	                    await transaction.CommitAsync();
347	
348	                    return BuchungErgebnis.Erfolg(new BuchungDto(
349	                        buchung.Referenz,
350	                        buchung.VeranstaltungId,
351	                        buchung.Name,
352	                        buchung.Email,
353	                        buchung.Status.ToString(),
354	                        buchung.Gesamtpreis,
355	                        positionen.Select(p => new BuchungspositionDto(
356	                            p.SitzplatzCode,
357	                            p.PreiskategorieId,
358	                            veranstaltung.Preiskategorien.First(k => k.Id == p.PreiskategorieId).Name,
359	                            p.PreisSnapshot)).ToList()));
360	                }
361	                catch (DbUpdateException)
362	                {
363	                    await transaction.RollbackAsync();
364	                    db.ChangeTracker.Clear();
365	
366	                    var tatsaechlichBelegt = await db.Sitzplatzbelegungen
367	                        .Where(s => s.VeranstaltungId == veranstaltungId && angefragteCodes.Contains(s.SitzplatzCode))
368	                        .Select(s => s.SitzplatzCode)
369	                        .ToListAsync();
370	
371	                    if (tatsaechlichBelegt.Count > 0)
372	                    {
373	                        return BuchungErgebnis.Konflikt(tatsaechlichBelegt);
374	                    }
375	
376	                    // Keiner der angefragten Plaetze ist tatsaechlich belegt: der Fehlschlag kam nicht von
377	                    // Sitzplatzbelegung, sondern von der UNIQUE-Constraint auf Buchung.Referenz. Naechster
378	                    // Versuch mit neuer Referenz (bis MaxReferenzVersuche erreicht ist).
379	                }
380	            }
381	
382	            return BuchungErgebnis.ReferenzFehlgeschlagen();
383	        }
384	    }
385	    ```
386	  - [ ] **Disaster Prevention — `db.ChangeTracker.Clear()` nach Rollback ist zwingend:** Ohne diesen Aufruf blieben `buchung`/`positionen`/`belegungen` aus dem gescheiterten Versuch im Change Tracker als `Added` markiert. Der nachfolgende `Sitzplatzbelegungen`-Read in derselben Methode würde dann fälschlich auch die (nie committeten) eigenen Entitäten des gescheiterten Versuchs zurückliefern, und ein zweiter Schleifendurchlauf würde versuchen, dieselben (jetzt doppelt getrackten) Entitäten erneut einzufügen — ein zweiter, verwirrender Fehler statt des korrekten Konflikt-/Retry-Verhaltens.
387	  - [ ] **Warum kein `try/catch` um die Preiskategorie-Prüfung, aber um `SaveChangesAsync`:** Die Preiskategorie-Prüfung (AC #4) ist eine reine In-Memory-Prüfung gegen bereits geladene Daten (`veranstaltung.Preiskategorien`), kein DB-Schreibzugriff — sie muss **vor** dem ersten Transaktionsversuch passieren, nicht als Teil der Retry-Schleife, da eine ungültige Preiskategorie sich durch Wiederholen nicht "repariert".
388	  - [ ] **Warum die Unterscheidung Konflikt vs. Referenz-Kollision ohne Exception-Message-Parsing funktioniert (AD-4-Konformität):** Beide Fälle lösen dieselbe `DbUpdateException` bei `SaveChangesAsync` aus (verschiedene `UNIQUE`-Constraints). Statt die SQL-Fehlermeldung zu parsen, liest der Code nach dem Rollback erneut, ob einer der **angefragten** Sitzplätze tatsächlich als `Sitzplatzbelegung`-Zeile existiert. Da die Referenz vollständig unabhängig von den Sitzplatz-Codes ist, kann eine reine Referenz-Kollision niemals dazu führen, dass einer der angefragten Sitzplätze plötzlich als belegt erscheint — der Read liefert in diesem Fall zuverlässig eine leere Liste, und die Schleife interpretiert das korrekt als "nächster Referenz-Versuch nötig".
389	
390	- [ ] Task 7: Controller-Endpunkt `POST /veranstaltungen/{id}/buchungen` (AC: #1, #2, #3, #4, #5)
391	  - [ ] `seed-a-backend.Api/Controllers/VeranstaltungenController.cs`: Konstruktor um `IBuchungenService buchungenService` erweitern:
392	    ```csharp
